// GERADO por scripts/gera-mapa-features.mjs — não editar à mão.
window.AVAL_MAPA = {"produto":{"nome":"GPE","desc":"","path":"global/MASTER.md"},"dominios":[{"folder":"acesso-usuarios","nome":"Acesso e Usuários","sigla":"ACE","desc":"Cuida de quem entra no sistema e do que cada um pode fazer. Reúne a entrada e a saída do sistema, a recuperação e a troca de senha, os dados do usuário logado e a manutenção dos usuários com seus perfis. Atende os três perfis que operam o GPE — Administrador, Secretaria Mesa e Secretaria Check-In — e, na manutenção de usuários, só o Administrador.","path":"modules/acesso-usuarios/README.md","fss":[{"nome":"Autenticação","sigla":"ACE-AUT","desc":"Reúne o que o usuário faz com a própria conta: entrar no sistema com usuário e senha, sair, pedir uma senha temporária quando esquece a sua, trocar a senha — por obrigação, no primeiro acesso, ou por vontade própria —, ver os dados com que está logado e trocar a foto de perfil. Todas as operações são feitas sobre o cadastro corporativo da CNI. Corresponde ao documento legado **GPE001 – Efetuar Login**.","path":"modules/acesso-usuarios/autenticacao/README.md","feats":[{"id":"ACE-AUT-01","nome":"Autenticar Usuário","desc":"Permite que o usuário entre no sistema informando usuário e senha; autenticado no cadastro corporativo da CNI, ele chega à tela inicial do seu perfil, com o menu que esse perfil enxerga.","objeto":"Quem acessa o sistema, com o perfil que define o que pode fazer.","uso":"A tela de acesso é a primeira que o sistema mostra a quem não tem sessão aberta, qualquer que seja o endereço digitado. O usuário informa Usuário e Senha e aciona Entrar; quem esqueceu a senha segue pelo atalho \"Esqueceu a senha?\".","estado":"rascunho","mvp":false,"path":"modules/acesso-usuarios/autenticacao/f-autenticar-usuario.md","codigo":{"back":[],"front":[]}},{"id":"ACE-AUT-02","nome":"Encerrar Sessão","desc":"Permite que o usuário encerre a sua sessão no sistema; ele volta à tela de acesso e, para usar o sistema de novo naquele navegador, precisa autenticar-se outra vez.","objeto":"Quem acessa o sistema, com o perfil que define o que pode fazer.","uso":"A saída é acionada pela opção Logout, no menu que se abre ao clicar na foto ou no nome do usuário, no cabeçalho de qualquer tela interna. Não há dado a informar nem confirmação a dar.","estado":"rascunho","mvp":false,"path":"modules/acesso-usuarios/autenticacao/f-encerrar-sessao.md","codigo":{"back":[],"front":[]}},{"id":"ACE-AUT-03","nome":"Recuperar Senha","desc":"Permite que o usuário que esqueceu a senha recupere o acesso informando apenas o seu login; o cadastro corporativo da CNI envia a ele uma senha temporária, com a qual volta a entrar no sistema.","objeto":"Quem acessa o sistema, com o perfil que define o que pode fazer.","uso":"Chega-se pelo atalho \"Esqueceu a senha?\", na tela de acesso, sem precisar estar autenticado. O usuário informa o login no campo Usuário e aciona Recuperar senha; o botão Voltar retorna à tela de acesso sem pedir nada.","estado":"rascunho","mvp":false,"path":"modules/acesso-usuarios/autenticacao/f-recuperar-senha.md","codigo":{"back":[],"front":[]}},{"id":"ACE-AUT-04","nome":"Alterar Senha","desc":"Permite que o usuário altere a senha com que entra no sistema — por obrigação, quando a senha em uso é provisória, ou por vontade própria, a qualquer momento; a nova senha passa a valer de imediato e ele segue autenticado com ela.","objeto":"Quem acessa o sistema, com o perfil que define o que pode fazer.","uso":"Na troca obrigatória, a tela se abre sozinha quando o usuário tenta entrar com a senha provisória, e pede só a nova senha e a sua confirmação. Na voluntária, o usuário já autenticado abre a tela pela opção Alterar Senha do menu do usuário e informa também a senha atual. Nos dois casos, a troca é feita pelo botão Alterar Senha.","estado":"rascunho","mvp":false,"path":"modules/acesso-usuarios/autenticacao/f-alterar-senha.md","codigo":{"back":[],"front":[]}},{"id":"ACE-AUT-05","nome":"Alterar Foto de Perfil","desc":"Permite que o usuário altere a foto que o identifica no cabeçalho do sistema, escolhendo uma imagem do seu computador; a nova foto passa a aparecer ao lado do nome dele em todas as telas internas.","objeto":"Quem acessa o sistema, com o perfil que define o que pode fazer.","uso":"Pelo documento legado, o usuário aciona a opção Alterar Foto do Perfil, no menu do usuário, escolhe a imagem na janela que se abre e a salva 📄. ⚠️ **Hoje a troca não pode ser feita pela tela**: a opção existe no menu, mas não abre janela nenhuma — a rotina que grava a foto está no código e nada na tela a aciona 💻.","estado":"rascunho","mvp":false,"path":"modules/acesso-usuarios/autenticacao/f-alterar-foto-perfil.md","codigo":{"back":[],"front":[]}},{"id":"ACE-AUT-06","nome":"Consultar Dados do Usuário","desc":"Permite que o usuário consulte os dados da conta com que está autenticado — nome, login, perfil e e-mail —, confirmando com qual conta e com qual perfil está operando o sistema.","objeto":"Quem acessa o sistema, com o perfil que define o que pode fazer.","uso":"Os dados aparecem no menu que se abre ao clicar na foto ou no nome do usuário, no cabeçalho de qualquer tela interna. Não há nada a informar; o mesmo menu traz as opções Alterar Foto do Perfil, Alterar Senha e Logout.","estado":"rascunho","mvp":false,"path":"modules/acesso-usuarios/autenticacao/f-consultar-dados-usuario.md","codigo":{"back":[],"front":[]}}]},{"nome":"Usuários","sigla":"ACE-USU","desc":"Reúne a manutenção dos usuários do sistema pelo Administrador: localizar um usuário, incluí-lo a partir da validação do seu login, alterar seus dados e seu perfil, e excluí-lo. O usuário é mantido no cadastro corporativo da CNI — a tela do GPE opera sobre ele e define o perfil que a pessoa terá neste sistema. Corresponde ao documento legado **GPE002 – Manter Usuário**.","path":"modules/acesso-usuarios/usuarios/README.md","feats":[{"id":"ACE-USU-01","nome":"Pesquisar Usuários","desc":"Permite que o Administrador localize os usuários do sistema por entidade, perfil, nome ou login e veja, de cada um, o login, o e-mail, o perfil, a situação e quem o cadastrou e o alterou por último.","objeto":"Quem acessa o sistema, com o perfil que define o que pode fazer.","uso":"Chega-se pela opção de menu Administração › Usuários. A tela abre já com todos os usuários listados; para restringir a lista, informam-se os filtros e aciona-se \"Pesquisar\". É da lista que partem a inclusão, a edição e a exclusão de usuário.","estado":"rascunho","mvp":false,"path":"modules/acesso-usuarios/usuarios/f-pesquisar-usuarios.md","codigo":{"back":[],"front":[]}},{"id":"ACE-USU-02","nome":"Cadastrar Usuário","desc":"Permite que o Administrador inclua um usuário no sistema a partir do login validado, informando os dados dele e o perfil de acesso; o usuário passa a constar na lista de usuários, com a situação Ativo.","objeto":"Quem acessa o sistema, com o perfil que define o que pode fazer.","uso":"Chega-se pelo botão \"Adicionar\" da tela Usuários. Informa-se o login e aciona-se \"Validar Login\"; aceito o login, o sistema abre o formulário — já preenchido e bloqueado quando o usuário é interno da CNI —, escolhe-se o perfil e conclui-se em \"Cadastrar Usuário\".","estado":"rascunho","mvp":false,"path":"modules/acesso-usuarios/usuarios/f-cadastrar-usuario.md","codigo":{"back":[],"front":[]}},{"id":"ACE-USU-03","nome":"Editar Usuário","desc":"Permite que o Administrador altere os dados e o perfil de acesso de um usuário já cadastrado, sem mudar o login; as alterações passam a valer no cadastro do usuário e aparecem na lista de usuários.","objeto":"Quem acessa o sistema, com o perfil que define o que pode fazer.","uso":"A edição é aberta pelo ícone de lápis de cada linha da lista de usuários. O formulário vem preenchido, com o login bloqueado; quando o usuário é interno da CNI, só o perfil e as instituições relacionadas podem ser alterados. Conclui-se em \"Atualizar Usuário\".","estado":"rascunho","mvp":false,"path":"modules/acesso-usuarios/usuarios/f-editar-usuario.md","codigo":{"back":[],"front":[]}},{"id":"ACE-USU-04","nome":"Excluir Usuário","desc":"Permite que o Administrador exclua um usuário do sistema, mediante confirmação; o usuário deixa de ser exibido na lista de usuários.","objeto":"Quem acessa o sistema, com o perfil que define o que pode fazer.","uso":"A exclusão é acionada pela opção Remover Usuário, em cada linha da lista de usuários. O sistema pede confirmação e, confirmada, solicita a exclusão ao cadastro corporativo e retira a linha da lista.","estado":"rascunho","mvp":false,"path":"modules/acesso-usuarios/usuarios/f-excluir-usuario.md","codigo":{"back":[],"front":[]}}]}]},{"folder":"eventos","nome":"Eventos","sigla":"EVT","desc":"Cuida do evento do começo ao fim: o cadastro da reunião, do comitê ou do seminário; a lista de quem foi convidado e de quem confirmou; a chegada dos participantes no dia; o lugar de cada um na mesa; e a legenda que classifica cada participante. Atende o Administrador, que prepara o evento, a Secretaria Check-In, que recebe os participantes, e a Secretaria Mesa, que os conduz aos lugares.","path":"modules/eventos/README.md","fss":[{"nome":"Cadastro de Eventos","sigla":"EVT-CAD","desc":"Reúne a manutenção dos eventos e a formação da lista de participantes de cada um. O Administrador localiza um evento, inclui, altera, visualiza e exclui; define qual é o evento principal, aquele sobre o qual a recepção e a secretaria de mesa trabalham; e traz para o evento as pessoas — por planilha de convidados, por planilha de confirmados ou importando do CRM os inscritos da campanha. Corresponde ao documento legado **GPE004 – Manter Evento**.","path":"modules/eventos/cadastro-eventos/README.md","feats":[{"id":"EVT-CAD-01","nome":"Pesquisar Eventos","desc":"Permite que o Administrador pesquise os eventos cadastrados por nome, local, tipo de evento, tipo de mesa ou data, e veja de cada um a data e o horário, o local, o tipo, o formato da mesa, a quantidade de participantes e se é o evento principal.","objeto":"**ALI: Evento** · entidade principal A reunião, o comitê ou o seminário que a CNI organiza: o que acontece, quando, onde e com que formato de mesa.","uso":"A pesquisa abre pelo menu Eventos › Cadastro e já traz todos os eventos, do incluído por último para o mais antigo. O Administrador informa um ou mais filtros e aciona Pesquisar; de cada linha do resultado partem as ações sobre o evento, como visualizar, editar e excluir.","estado":"rascunho","mvp":false,"path":"modules/eventos/cadastro-eventos/f-pesquisar-eventos.md","codigo":{"back":[],"front":[]}},{"id":"EVT-CAD-02","nome":"Cadastrar Evento","desc":"Permite que o Administrador cadastre um evento com nome, data e hora, local, tipo de evento, tipo de mesa e quantidade prevista de participantes; o evento passa a constar na pesquisa de eventos, já com os assentos do mapa gerados conforme o tipo de mesa.","objeto":"**ALI: Evento** · entidade principal A reunião, o comitê ou o seminário que a CNI organiza: o que acontece, quando, onde e com que formato de mesa.","uso":"O cadastro é aberto pelo botão Adicionar da tela Eventos. O Administrador preenche os campos, pode informar o Código da Campanha do CRM e anexar uma imagem, e aciona Salvar; o sistema volta à lista de eventos.","estado":"rascunho","mvp":false,"path":"modules/eventos/cadastro-eventos/f-cadastrar-evento.md","codigo":{"back":[],"front":[]}},{"id":"EVT-CAD-03","nome":"Editar Evento","desc":"Permite que o Administrador altere os dados básicos de um evento já cadastrado, inclusive o nome; a pesquisa de eventos e as demais telas do evento passam a mostrar os dados novos, sem que os participantes, os check-ins e os assentos sejam tocados.","objeto":"**ALI: Evento** · entidade principal A reunião, o comitê ou o seminário que a CNI organiza: o que acontece, quando, onde e com que formato de mesa.","uso":"A edição é aberta pelo ícone Editar evento, em cada linha da lista de eventos. A tela vem preenchida com os dados atuais; o Administrador altera o que precisa e aciona Salvar, e o sistema volta à lista de eventos.","estado":"rascunho","mvp":false,"path":"modules/eventos/cadastro-eventos/f-editar-evento.md","codigo":{"back":[],"front":[]}},{"id":"EVT-CAD-04","nome":"Visualizar Evento","desc":"Permite que o Administrador visualize os dados básicos de um evento em modo de leitura, sem poder alterá-los, e baixe a imagem anexada a ele.","objeto":"**ALI: Evento** · entidade principal A reunião, o comitê ou o seminário que a CNI organiza: o que acontece, quando, onde e com que formato de mesa.","uso":"A visualização é aberta pelo ícone Visualizar evento, em cada linha da lista de eventos. A tela mostra cada dado como texto e oferece apenas o botão Voltar.","estado":"rascunho","mvp":false,"path":"modules/eventos/cadastro-eventos/f-visualizar-evento.md","codigo":{"back":[],"front":[]}},{"id":"EVT-CAD-05","nome":"Excluir Evento","desc":"Permite que o Administrador exclua um evento; o evento deixa de aparecer na pesquisa de eventos, e os seus dados, com os participantes e os assentos, permanecem guardados.","objeto":"**ALI: Evento** · entidade principal A reunião, o comitê ou o seminário que a CNI organiza: o que acontece, quando, onde e com que formato de mesa.","uso":"A exclusão é acionada pelo ícone Excluir evento, em cada linha da lista de eventos. O sistema pede confirmação e, confirmada, retira o evento da lista.","estado":"rascunho","mvp":false,"path":"modules/eventos/cadastro-eventos/f-excluir-evento.md","codigo":{"back":[],"front":[]}},{"id":"EVT-CAD-06","nome":"Definir Evento Principal","desc":"Permite que o Administrador defina um evento como o principal; ele passa a ser o evento em que a Secretaria Check-In e a Secretaria Mesa trabalham, e o evento que era o principal deixa de sê-lo.","objeto":"**ALI: Evento** · entidade principal A reunião, o comitê ou o seminário que a CNI organiza: o que acontece, quando, onde e com que formato de mesa.","uso":"A ação é acionada pelo ícone de bandeira Tornar evento principal, na linha de cada evento que ainda não é o principal. Não pede confirmação nem dado algum: a troca vale assim que o ícone é acionado.","estado":"rascunho","mvp":false,"path":"modules/eventos/cadastro-eventos/f-definir-evento-principal.md","codigo":{"back":[],"front":[]}},{"id":"EVT-CAD-07","nome":"Carregar Convidados","desc":"Permite que o Administrador carregue de uma planilha a lista de convidados de um evento; cada pessoa da planilha é incluída no cadastro de pessoas, ou atualizada nele, e passa a constar no evento como convidada.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) A participação de uma pessoa em um evento — o **participante**. Guarda o que aconteceu com ela naquele evento: convite, confirmação, check-in, atendimento e assento.","uso":"A carga fica na janela Cargas de Convidados e Confirmados, aberta pelo ícone de pasta em cada linha da lista de eventos. O Administrador adiciona a planilha na seção Carga de Convidados e aciona Enviar; a janela fecha, e o sistema avisa quando a carga termina.","estado":"rascunho","mvp":false,"path":"modules/eventos/cadastro-eventos/f-carregar-convidados.md","codigo":{"back":[],"front":[]}},{"id":"EVT-CAD-08","nome":"Carregar Confirmados","desc":"Permite que o Administrador carregue de uma planilha a relação de quem confirmou presença em um evento; cada pessoa da planilha fica marcada como confirmada naquele evento, e a que ainda não tem cadastro é incluída no cadastro de pessoas.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) A participação de uma pessoa em um evento — o **participante**. Guarda o que aconteceu com ela naquele evento: convite, confirmação, check-in, atendimento e assento.","uso":"A carga fica na janela Cargas de Convidados e Confirmados, aberta pelo ícone de pasta em cada linha da lista de eventos. O Administrador adiciona a planilha na seção Carga de Confirmados e aciona Enviar; a janela fecha, e o sistema avisa quando a carga termina.","estado":"rascunho","mvp":false,"path":"modules/eventos/cadastro-eventos/f-carregar-confirmados.md","codigo":{"back":[],"front":[]}},{"id":"EVT-CAD-09","nome":"Importar Inscritos do CRM","desc":"Permite que o Administrador importe do CRM os inscritos aprovados e confirmados da campanha de um evento, sem digitação; cada inscrito passa a constar no evento como convidado e confirmado, e a pessoa é incluída no cadastro de pessoas ou atualizada nele.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) A participação de uma pessoa em um evento — o **participante**. Guarda o que aconteceu com ela naquele evento: convite, confirmação, check-in, atendimento e assento.","uso":"A importação fica na seção Inscritos do CRM da janela Cargas de Convidados e Confirmados, aberta pelo ícone de pasta em cada linha da lista de eventos. O evento precisa ter o Código da Campanha; o Administrador aciona Importar Inscritos do CRM e recebe o resumo do que foi importado.","estado":"rascunho","mvp":false,"path":"modules/eventos/cadastro-eventos/f-importar-inscritos-crm.md","codigo":{"back":[],"front":[]}}]},{"nome":"Legendas","sigla":"EVT-LEG","desc":"Reúne a classificação dos participantes por legenda. A legenda é uma categoria com nome e cor — Anfitrião, Palestrantes, Diretores da CNI — que identifica o participante na lista e no mapa de assentos. O Administrador mantém um **catálogo** de blocos de legenda, comum a todos os eventos, e em cada evento monta a **configuração**: escolhe os blocos, põe-nos em ordem de prioridade e define as **condições** que dizem quem recebe cada legenda. Antes de aplicar, pode **simular**; ao **gerar**, o sistema atribui as legendas aos participantes do evento. Uma configuração pode ser guardada como **preset** e reaproveitada em outro evento. Corresponde ao documento legado **GPE006 – Gerenciar Regras de Legendas**, reformulado pelo ticket `PDTIC25148-34` (Configuração de Legendas por Evento, em teste).","path":"modules/eventos/legendas/README.md","feats":[{"id":"EVT-LEG-01","nome":"Consultar Configuração de Legendas","desc":"Permite que o Administrador consulte a configuração de legendas de um evento: os blocos de legenda em ordem de prioridade, cada um com seu número, sua cor, seu nome e as condições que decidem quem recebe a legenda.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) Um bloco de legenda colocado na configuração de um evento. É a presença do bloco que o põe em vigor naquele evento.","uso":"A consulta abre pelo ícone Configuração de Legendas, em cada linha da lista de eventos. A tela mostra um cartão por bloco, sem pedir nenhum dado, e é dela que partem as demais ações sobre a configuração, como adicionar bloco, simular e gerar as legendas. O que se altera nessa tela é gravado na hora, sem botão de salvar.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-consultar-configuracao-legendas.md","codigo":{"back":[],"front":[]}},{"id":"EVT-LEG-02","nome":"Adicionar Bloco de Legenda ao Evento","desc":"Permite que o Administrador adicione à configuração de legendas de um evento um ou mais blocos do catálogo; cada bloco entra no fim da ordem, ainda sem condições, e passa a fazer parte das legendas daquele evento.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) Um bloco de legenda colocado na configuração de um evento. É a presença do bloco que o põe em vigor naquele evento.","uso":"Na tela Configuração de Legendas, o botão Adicionar bloco abre uma janela com os blocos do catálogo que ainda não estão no evento. O usuário busca pelo nome, marca os blocos que quer e aciona Adicionar ao evento.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-adicionar-bloco-legenda.md","codigo":{"back":[],"front":[]}},{"id":"EVT-LEG-03","nome":"Configurar Condições de Legenda","desc":"Permite que o Administrador configure, em um bloco de legenda do evento, as condições de campo, operador e valor que decidem quais participantes recebem a legenda, combinando-as com os conectivos E e OU.","objeto":"**ALI: Evento** · subgrupo (entidade atributiva do bloco do evento) Uma condição de um bloco: o teste que decide se o participante recebe a legenda.","uso":"No cartão do bloco, na tela Configuração de Legendas, o botão Adicionar condição cria uma linha; o usuário escolhe o campo e o operador, digita o valor e, a partir da segunda condição, escolhe o conectivo. A lixeira da linha exclui a condição. Cada mudança é gravada na hora.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-configurar-condicoes-legenda.md","codigo":{"back":[],"front":[]}},{"id":"EVT-LEG-04","nome":"Reordenar Blocos de Legenda","desc":"Permite que o Administrador reordene os blocos de legenda da configuração de um evento, movendo um bloco uma posição para cima ou para baixo; os números são recalculados e a nova ordem passa a ser a prioridade das legendas.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) Um bloco de legenda colocado na configuração de um evento. É a presença do bloco que o põe em vigor naquele evento.","uso":"No cartão do bloco, na tela Configuração de Legendas, as setas Mover para cima e Mover para baixo trocam o bloco de lugar com o vizinho. A troca é gravada na hora.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-reordenar-blocos-legenda.md","codigo":{"back":[],"front":[]}},{"id":"EVT-LEG-05","nome":"Remover Bloco de Legenda do Evento","desc":"Permite que o Administrador remova um bloco de legenda da configuração de um evento, com as condições que ele tinha ali; o bloco deixa de valer naquele evento e continua no catálogo, disponível para os demais eventos e para ser adicionado de novo.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) Um bloco de legenda colocado na configuração de um evento. É a presença do bloco que o põe em vigor naquele evento.","uso":"No cartão do bloco, na tela Configuração de Legendas, o botão Remover bloco do evento pede confirmação e, confirmada, retira o bloco e renumera os que ficam.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-remover-bloco-legenda.md","codigo":{"back":[],"front":[]}},{"id":"EVT-LEG-06","nome":"Simular Aplicação de Legendas","desc":"Permite que o Administrador simule a aplicação da configuração de legendas de um evento e veja quantos e quais participantes receberiam cada legenda, sem alterar nenhuma legenda nem a configuração gravada.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do participante) A legenda que um participante recebeu num evento — por regra ou manualmente.","uso":"Na tela Configuração de Legendas, o botão Simular avalia a configuração como está na tela e abre uma janela com os totais (Participantes, Legendas removidas, Legendas aplicadas e Manuais preservadas) e uma tabela por legenda, que se expande para mostrar os nomes dos participantes. Da janela pode-se seguir direto para a geração, pelo botão Executar.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-simular-aplicacao-legendas.md","codigo":{"back":[],"front":[]}},{"id":"EVT-LEG-07","nome":"Gerar Legendas do Evento","desc":"Permite que o Administrador gere as legendas dos participantes de um evento: o sistema apaga as legendas atribuídas por regra, avalia as condições de cada bloco da configuração e atribui a legenda a quem as atende, preservando as legendas atribuídas manualmente.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do participante) A legenda que um participante recebeu num evento — por regra ou manualmente.","uso":"Na tela Configuração de Legendas, o botão Executar pede confirmação e, confirmada, aplica a configuração que está na tela. O mesmo botão existe na janela da simulação. Ao final, o sistema informa quantas legendas foram aplicadas e quantas manuais foram preservadas.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-gerar-legendas-evento.md","codigo":{"back":[],"front":[]}},{"id":"EVT-LEG-08","nome":"Salvar Preset de Legendas","desc":"Permite que o Administrador guarde com um nome a configuração de legendas do evento — os blocos, a ordem e as condições —, deixando-a disponível na biblioteca de presets para ser aplicada a qualquer outro evento.","objeto":"**ALI: PresetLegenda** · entidade principal Uma configuração de legendas guardada com nome, para ser reaproveitada em outros eventos.","uso":"Na tela Configuração de Legendas do evento, o botão Salvar como preset abre uma janela que pede o nome e, se desejado, uma descrição. Confirmado, o preset passa a constar na Biblioteca de presets, de onde é aplicado por Carregar Configuração de Legendas.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-salvar-preset-legendas.md","codigo":{"back":[],"front":[]}},{"id":"EVT-LEG-09","nome":"Carregar Configuração de Legendas","desc":"Permite que o Administrador traga para o evento a configuração de legendas guardada em um preset ou montada em outro evento, substituindo a configuração atual ou acrescentando a ela os blocos que faltam; o evento passa a ter os blocos, a ordem e as condições trazidos.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) Um bloco de legenda colocado na configuração de um evento. É a presença do bloco que o põe em vigor naquele evento.","uso":"Na tela Configuração de Legendas, o botão Carregar configuração abre uma janela em que se escolhe o modo — substituir ou mesclar — e, na aba Biblioteca de presets ou na aba De outro evento, aciona-se Aplicar ao evento na origem desejada. A configuração resultante é gravada na hora.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-carregar-configuracao-legendas.md","codigo":{"back":[],"front":[]}},{"id":"EVT-LEG-10","nome":"Excluir Preset de Legendas","desc":"Permite que o Administrador exclua da biblioteca um preset de legendas que não serve mais; o preset deixa de ser oferecido para aplicação, e os eventos em que ele já foi aplicado continuam com a configuração que têm.","objeto":"**ALI: PresetLegenda** · entidade principal Uma configuração de legendas guardada com nome, para ser reaproveitada em outros eventos.","uso":"Na janela Carregar configuração, aba Biblioteca de presets, cada preset tem o botão Excluir preset. O sistema pede confirmação e, confirmada, retira o preset e atualiza a lista.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-excluir-preset-legendas.md","codigo":{"back":[],"front":[]}},{"id":"EVT-LEG-11","nome":"Pesquisar Blocos de Legenda","desc":"Permite que o Administrador pesquise, pelo nome, os blocos de legenda do catálogo comum a todos os eventos, vendo de cada um o nome e a cor que o identifica.","objeto":"**ALI: Legenda** · entidade principal Um bloco do catálogo de legendas: a categoria que classifica o participante (por exemplo, Anfitrião ou Palestrantes), com a cor que a identifica na lista e no mapa. Na tela é chamada de **bloco**.","uso":"O catálogo abre pelo menu Administração › Catálogo de legendas ou pelo botão Gerenciar catálogo da Configuração de Legendas de um evento. Digita-se parte do nome no campo de busca e a lista se atualiza sozinha; de cada linha partem a edição e a exclusão do bloco, e do cabeçalho, a inclusão de um novo.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-pesquisar-blocos-legenda.md","codigo":{"back":[],"front":[]}},{"id":"EVT-LEG-12","nome":"Cadastrar Bloco de Legenda","desc":"Permite que o Administrador inclua no catálogo um bloco de legenda, com nome e cor; o bloco fica disponível para ser usado na configuração de legendas de qualquer evento.","objeto":"**ALI: Legenda** · entidade principal Um bloco do catálogo de legendas: a categoria que classifica o participante (por exemplo, Anfitrião ou Palestrantes), com a cor que a identifica na lista e no mapa. Na tela é chamada de **bloco**.","uso":"No Catálogo de blocos, o botão Novo bloco abre uma janela com o nome e a cor. O mesmo cadastro pode ser feito sem sair da configuração de um evento, pela aba Criar novo bloco da janela Adicionar bloco; nesse caso, o bloco criado já entra na configuração do evento.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-cadastrar-bloco-legenda.md","codigo":{"back":[],"front":[]}},{"id":"EVT-LEG-13","nome":"Editar Bloco de Legenda","desc":"Permite que o Administrador altere o nome ou a cor de um bloco de legenda do catálogo; a mudança passa a valer em todos os eventos que usam o bloco e nas legendas já atribuídas aos participantes.","objeto":"**ALI: Legenda** · entidade principal Um bloco do catálogo de legendas: a categoria que classifica o participante (por exemplo, Anfitrião ou Palestrantes), com a cor que a identifica na lista e no mapa. Na tela é chamada de **bloco**.","uso":"No Catálogo de blocos, o ícone de lápis de cada linha abre a janela Editar bloco com o nome e a cor atuais. Altera-se o que for preciso e aciona-se Salvar.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-editar-bloco-legenda.md","codigo":{"back":[],"front":[]}},{"id":"EVT-LEG-14","nome":"Excluir Bloco de Legenda","desc":"Permite que o Administrador exclua um bloco de legenda do catálogo; o bloco deixa de existir e sai, junto, da configuração de todos os eventos que o usam e das legendas dos participantes que o tinham recebido.","objeto":"**ALI: Legenda** · entidade principal Um bloco do catálogo de legendas: a categoria que classifica o participante (por exemplo, Anfitrião ou Palestrantes), com a cor que a identifica na lista e no mapa. Na tela é chamada de **bloco**.","uso":"No Catálogo de blocos, o ícone de lixeira de cada linha consulta onde o bloco está em uso e pede confirmação, avisando quando há eventos afetados. Confirmada a exclusão, o bloco é retirado e a lista é atualizada.","estado":"rascunho","mvp":false,"path":"modules/eventos/legendas/f-excluir-bloco-legenda.md","codigo":{"back":[],"front":[]}}]},{"nome":"Participantes","sigla":"EVT-PAR","desc":"Reúne o que acontece com os participantes de um evento, antes e durante a sua realização. Na **lista de participantes**, localiza-se a pessoa, registra-se o check-in, ajusta-se a confirmação de presença, inclui-se quem chegou sem estar na lista e trata-se a legenda de cada um. No **mapa de assentos**, o Administrador distribui os participantes pelos lugares da mesa, e a Secretaria Mesa acompanha quem já chegou, localiza o assento e marca quem foi atendido. Lista e mapa podem ser exportados. Corresponde ao documento legado **GPE005 – Gerenciar Participante**.","path":"modules/eventos/participantes/README.md","feats":[{"id":"EVT-PAR-01","nome":"Pesquisar Participantes","desc":"Permite que a equipe do evento pesquise os participantes por nome, organização, cargo, legenda, tema, grupo de trabalho ou situação de convite, confirmação e check-in; o resultado mostra, para cada pessoa, a legenda, a situação no evento e o assento.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) A participação de uma pessoa em um evento — o **participante**. Guarda o que aconteceu com ela naquele evento: convite, confirmação, check-in, atendimento e assento.","uso":"A pesquisa fica na tela de participantes, aberta pela opção Participantes de cada evento na pesquisa de eventos. Informam-se os critérios desejados, como o texto da busca, as legendas e a situação de check-in, e aciona-se Pesquisar; o texto da busca pesquisa sozinho, enquanto é digitado.","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-pesquisar-participantes.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-02","nome":"Cadastrar Participante","desc":"Permite que a recepção do evento cadastre, na hora, uma pessoa que não estava na lista: ela entra no cadastro de pessoas e passa a ser participante do evento, já com o check-in registrado quando assim indicado.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) A participação de uma pessoa em um evento — o **participante**. Guarda o que aconteceu com ela naquele evento: convite, confirmação, check-in, atendimento e assento.","uso":"O cadastro é aberto pelo botão Cadastrar Pessoa, no cabeçalho da tela de participantes. Informam-se o nome completo, a instituição ou empresa, o cargo e o e-mail, decide-se se o check-in é automático e aciona-se Enviar.","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-cadastrar-participante.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-03","nome":"Registrar Check-in","desc":"Permite que a recepção do evento registre a chegada de um participante, marcando o check-in na lista; ele passa a constar como presente e entra na fila de atendimento da secretaria de mesa. A mesma ação desfaz um check-in marcado por engano.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) A participação de uma pessoa em um evento — o **participante**. Guarda o que aconteceu com ela naquele evento: convite, confirmação, check-in, atendimento e assento.","uso":"O check-in é marcado e desmarcado pelo ícone da coluna Check-In, em cada linha da lista de participantes. Um toque basta: o sistema não pede confirmação.","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-registrar-check-in.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-04","nome":"Consultar Legenda do Participante","desc":"Permite que o Administrador consulte, para um participante do evento, a legenda que lhe foi atribuída manualmente e as legendas do catálogo que podem ser atribuídas a ele, com a indicação das que fazem parte da configuração do evento.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do participante) A legenda que um participante recebeu num evento — por regra ou manualmente.","uso":"A consulta abre na janela Gerenciar Legenda da Pessoa, acionada pelo valor da coluna Assento, na linha do participante. É dessa janela que partem a alteração e a remoção da legenda.","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-consultar-legenda-participante.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-05","nome":"Alterar Legenda do Participante","desc":"Permite que o Administrador altere a legenda de um participante do evento, atribuindo-lhe manualmente uma legenda do catálogo; a legenda escolhida passa a identificá-lo na lista e no mapa de assentos e não é desfeita quando as legendas do evento são geradas de novo.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do participante) A legenda que um participante recebeu num evento — por regra ou manualmente.","uso":"Na janela Gerenciar Legenda da Pessoa, escolhe-se uma legenda em Selecione uma Legenda e aciona-se Salvar.","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-alterar-legenda-participante.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-06","nome":"Remover Legenda do Participante","desc":"Permite que o Administrador remova a legenda atribuída manualmente a um participante do evento; ele volta a ser identificado pela legenda que recebeu por regra ou, se não tiver nenhuma, fica sem legenda.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do participante) A legenda que um participante recebeu num evento — por regra ou manualmente.","uso":"Na janela Gerenciar Legenda da Pessoa, aciona-se Remover Legenda e confirma-se a pergunta. O mesmo resultado se obtém escolhendo a opção Remover legenda, ao fim da lista de legendas, e acionando Salvar.","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-remover-legenda-participante.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-07","nome":"Consultar Mapa de Assentos","desc":"Permite que o Administrador e a Secretaria Mesa consultem o mapa de assentos de um evento, vendo cada assento com a sua identificação e o participante que o ocupa, ao lado da lista de pessoas disponíveis.","objeto":"**ALI: Evento** · subgrupo (os assentos nascem com o evento) Um assento do mapa do evento, com identificador fixo. Os assentos nascem com o evento.","uso":"O Administrador chega ao mapa pela opção \"Mapa de Assentos\" da tela de participantes do evento; a Secretaria Mesa já entra nele ao se autenticar, no evento principal. O mapa é montado conforme o formato de mesa do evento e se atualiza sozinho enquanto está aberto.","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-consultar-mapa-assentos.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-08","nome":"Atribuir Assento ao Participante","desc":"Permite que o Administrador atribua a um participante um assento do mapa do evento; o participante passa a ocupar o assento, sai da lista de pessoas disponíveis e fica localizável no mapa pela secretaria de mesa.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) A participação de uma pessoa em um evento — o **participante**. Guarda o que aconteceu com ela naquele evento: convite, confirmação, check-in, atendimento e assento.","uso":"No mapa de assentos, o Administrador arrasta a pessoa da lista \"Pessoas Disponíveis\" até o assento, arrasta-a de um assento para outro, ou clica no assento vazio e escolhe a pessoa na janela \"Selecionar Pessoa\". A alteração é gravada sozinha 30 segundos depois da última mudança, ou na hora pelo botão \"Salvar Alocações (n)\".","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-atribuir-assento-participante.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-09","nome":"Remover Assento do Participante","desc":"Permite que o Administrador remova um participante do assento que ele ocupa no mapa do evento; o assento fica vazio e o participante volta à lista de pessoas disponíveis, pronto para receber outro lugar.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) A participação de uma pessoa em um evento — o **participante**. Guarda o que aconteceu com ela naquele evento: convite, confirmação, check-in, atendimento e assento.","uso":"No mapa de assentos, cada assento ocupado traz o botão \"×\". Acionado, ele tira a pessoa do assento na hora, sem pedir confirmação; a remoção é gravada junto com o mapa, como na atribuição de assento.","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-remover-assento-participante.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-10","nome":"Registrar Atendimento","desc":"Permite que a Secretaria Mesa registre que um participante que chegou ao evento já foi atendido; o participante sai da lista de pessoas disponíveis, que fica só com quem ainda aguarda ser conduzido ao seu lugar.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) A participação de uma pessoa em um evento — o **participante**. Guarda o que aconteceu com ela naquele evento: convite, confirmação, check-in, atendimento e assento.","uso":"No mapa de assentos da Secretaria Mesa, cada pessoa da lista \"Pessoas Disponíveis\" traz o botão de atendimento — \"ATENDIDO\" no computador e \"ATENDER\" no tablet. Um toque no botão registra o atendimento, sem pedir confirmação.","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-registrar-atendimento.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-11","nome":"Liberar Todos os Assentos","desc":"Permite que o Administrador libere de uma só vez todos os assentos do mapa do evento; o mapa fica vazio e todos os participantes que estavam sentados voltam à lista de pessoas disponíveis, para que a distribuição recomece.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) A participação de uma pessoa em um evento — o **participante**. Guarda o que aconteceu com ela naquele evento: convite, confirmação, check-in, atendimento e assento.","uso":"No mapa de assentos, o botão \"Limpar Todas\", do painel \"Gerenciar Pessoas Alocadas na Mesa\", esvazia o mapa na hora, sem pedir confirmação.","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-liberar-assentos.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-12","nome":"Buscar Pessoa na Mesa","desc":"Permite que o Administrador e a Secretaria Mesa busquem, pelo nome, uma pessoa que já está sentada no mapa do evento; a busca informa em que assento ela está e destaca esse assento no mapa.","objeto":"**ALI: Evento** · subgrupo (os assentos nascem com o evento) Um assento do mapa do evento, com identificador fixo. Os assentos nascem com o evento.","uso":"No campo de busca que fica acima do mapa de assentos, digita-se parte do nome; os resultados aparecem enquanto se digita e, ao escolher uma pessoa, o assento dela é levado ao centro da tela e fica destacado por 5 segundos. No mapa da Secretaria Mesa também se pode digitar a identificação de um assento, como \"B15\".","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-buscar-pessoa-mesa.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-13","nome":"Alterar Confirmação de Presença","desc":"Permite que o Administrador altere a confirmação de presença de um participante, retirando a que veio do CRM ou das cargas, ou repondo-a; retirada a confirmação, o participante deixa de constar como confirmado e o assento que ocupava fica livre.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) A participação de uma pessoa em um evento — o **participante**. Guarda o que aconteceu com ela naquele evento: convite, confirmação, check-in, atendimento e assento.","uso":"A alteração é feita pelo ícone da coluna Confirmado, em cada linha da lista de participantes. O sistema pergunta antes de gravar, e só grava com a resposta afirmativa.","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-alterar-confirmacao-presenca.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-14","nome":"Exportar Participantes","desc":"Permite que a equipe do evento exporte para uma planilha os participantes que atendem à pesquisa em vigor, com os dados da pessoa, seus grupos de trabalho, temas e participações anteriores, a legenda e a situação de confirmação, check-in e atendimento.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) A participação de uma pessoa em um evento — o **participante**. Guarda o que aconteceu com ela naquele evento: convite, confirmação, check-in, atendimento e assento.","uso":"A exportação é acionada pelo botão Download, no rodapé da lista de participantes. O sistema baixa o arquivo Participantes.xls com os participantes que a última pesquisa encontrou, de todas as páginas.","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-exportar-participantes.md","codigo":{"back":[],"front":[]}},{"id":"EVT-PAR-15","nome":"Exportar Mapa de Assentos","desc":"Permite que o Administrador exporte o mapa de assentos do evento, inteiro ou só com a mesa principal, em um arquivo PDF ou de imagem que retrata os assentos e seus ocupantes como estão no mapa naquele momento.","objeto":"**ALI: Evento** · subgrupo (entidade associativa com atributos, dependente do evento) A participação de uma pessoa em um evento — o **participante**. Guarda o que aconteceu com ela naquele evento: convite, confirmação, check-in, atendimento e assento.","uso":"Na seção \"Exportações\", abaixo do mapa de assentos, há as linhas \"Mapa Completo:\" e \"Mesa do Presidente:\", cada uma com os botões \"PDF\" e \"PNG\". Um clique gera o arquivo e o baixa para o computador do usuário.","estado":"rascunho","mvp":false,"path":"modules/eventos/participantes/f-exportar-mapa-assentos.md","codigo":{"back":[],"front":[]}}]}]},{"folder":"pessoas","nome":"Pessoas","sigla":"PES","desc":"Mantém as pessoas que podem ser convidadas para os eventos e o que se sabe sobre cada uma: dados pessoais, contatos, a organização que representa, os grupos de trabalho de que participa, os temas a que se vincula e quantas vezes já participou de eventos. É a base de onde os eventos tiram seus participantes e de onde as regras de legenda tiram os dados que avaliam. Atende o Administrador.","path":"modules/pessoas/README.md","fss":[{"nome":"Cadastro de Pessoas","sigla":"PES-CAD","desc":"Reúne a manutenção das pessoas que podem ser convidadas para os eventos: localizar uma pessoa, incluí-la com seus dados pessoais, de contato e da organização que representa, alterar esses dados e excluí-la. Reúne também as três cargas de planilha que completam o cadastro com o que vem do CRM — os grupos de trabalho de que a pessoa participa, os temas a que se vincula e o histórico de participação em eventos. Corresponde ao documento legado **GPE003 – Manter Pessoa**.","path":"modules/pessoas/cadastro-pessoas/README.md","feats":[{"id":"PES-CAD-01","nome":"Pesquisar Pessoas","desc":"Permite que o Administrador localize pessoas do cadastro por nome, CRM, razão social ou e-mail; o resultado é a lista das pessoas encontradas, em ordem alfabética de nome, de onde se abre a edição ou a exclusão de cada uma.","objeto":"Quem pode participar de um evento: a pessoa convidada, com seus dados pessoais, de contato e da organização que representa.","uso":"Chega-se pelo menu Administração › Pessoas. A tela abre já com a lista de todas as pessoas; para restringir, o usuário preenche um ou mais filtros — Nome, CRM, Razão Social, E-mail — e aciona Pesquisar. Limpar esvazia os filtros e volta à lista completa.","estado":"rascunho","mvp":false,"path":"modules/pessoas/cadastro-pessoas/f-pesquisar-pessoas.md","codigo":{"back":[],"front":[]}},{"id":"PES-CAD-02","nome":"Cadastrar Pessoa","desc":"Permite que o Administrador inclua uma pessoa no cadastro, com seus dados pessoais, de contato e da organização que representa; a pessoa incluída passa a ser encontrada pela pesquisa de pessoas e fica disponível para os eventos.","objeto":"Quem pode participar de um evento: a pessoa convidada, com seus dados pessoais, de contato e da organização que representa.","uso":"Parte-se do botão Adicionar, na tela Pessoas. O usuário preenche as abas Cadastro, Contatos e Perfil Corporativo — são obrigatórios o Nome, a Razão Social e o Cargo — e aciona Criar.","estado":"rascunho","mvp":false,"path":"modules/pessoas/cadastro-pessoas/f-cadastrar-pessoa.md","codigo":{"back":[],"front":[]}},{"id":"PES-CAD-03","nome":"Editar Pessoa","desc":"Permite que o Administrador altere os dados pessoais, de contato e da organização de uma pessoa já cadastrada, e consulte na mesma tela os grupos de trabalho, os temas e o histórico de participação que as cargas de planilha trouxeram para ela.","objeto":"Quem pode participar de um evento: a pessoa convidada, com seus dados pessoais, de contato e da organização que representa.","uso":"Parte-se do ícone de lápis, em cada linha da lista de pessoas. A tela abre com os dados gravados; o usuário altera o que precisar nas abas Cadastro, Contatos e Perfil Corporativo e aciona Atualizar. As abas Relacionamento e Histórico servem só para consulta.","estado":"rascunho","mvp":false,"path":"modules/pessoas/cadastro-pessoas/f-editar-pessoa.md","codigo":{"back":[],"front":[]}},{"id":"PES-CAD-04","nome":"Excluir Pessoa","desc":"Permite que o Administrador exclua do cadastro uma pessoa que não participa de nenhum evento; a pessoa deixa de existir no sistema, junto com seus grupos de trabalho, temas e histórico de participação.","objeto":"Quem pode participar de um evento: a pessoa convidada, com seus dados pessoais, de contato e da organização que representa.","uso":"A exclusão é acionada pela opção Remover Pessoa, em cada linha da lista de pessoas. O sistema pede confirmação e, confirmada, retira a pessoa e atualiza a lista.","estado":"rascunho","mvp":false,"path":"modules/pessoas/cadastro-pessoas/f-excluir-pessoa.md","codigo":{"back":[],"front":[]}},{"id":"PES-CAD-05","nome":"Carregar Grupos de Trabalho","desc":"Permite que o Administrador traga, de uma planilha extraída do CRM, os grupos de trabalho de que as pessoas participam e o papel de cada uma neles; os grupos de trabalho que existiam no cadastro são todos substituídos pelos da planilha.","objeto":"Participação da pessoa em um grupo de trabalho, com o papel que ela desempenha nele. Só entra no sistema por carga de planilha.","uso":"Parte-se do botão Carga de GT, na tela Pessoas. O usuário escolhe a planilha, no formato .xlsx ou .xls, e aciona Enviar; ao terminar, o sistema informa quantos vínculos criou e quantas linhas ficaram sem pessoa correspondente.","estado":"rascunho","mvp":false,"path":"modules/pessoas/cadastro-pessoas/f-carregar-grupos-trabalho.md","codigo":{"back":[],"front":[]}},{"id":"PES-CAD-06","nome":"Carregar Temas","desc":"Permite que o Administrador traga, de uma planilha extraída do CRM, os temas de interesse a que as pessoas se vinculam; os temas que existiam no cadastro são todos substituídos pelos da planilha.","objeto":"Tema de interesse ao qual a pessoa está vinculada. Só entra no sistema por carga de planilha.","uso":"Parte-se do botão Carga de Temas, na tela Pessoas. O usuário escolhe a planilha, no formato .xlsx ou .xls, e aciona Enviar; ao terminar, o sistema informa quantos temas vinculou e quantas linhas ficaram sem pessoa correspondente.","estado":"rascunho","mvp":false,"path":"modules/pessoas/cadastro-pessoas/f-carregar-temas.md","codigo":{"back":[],"front":[]}},{"id":"PES-CAD-07","nome":"Carregar Histórico de Participação","desc":"Permite que o Administrador traga, de uma planilha extraída do CRM, quantas vezes cada pessoa participou de eventos em cada ano; o histórico das pessoas presentes na planilha é substituído pelo que ela traz, e o das demais não muda.","objeto":"Quantas vezes a pessoa participou de eventos em um ano. Só entra no sistema por carga de planilha.","uso":"Parte-se do botão Carga de Histórico, na tela Pessoas. O usuário escolhe a planilha, no formato .xlsx ou .xls, e aciona Enviar; ao terminar, o sistema informa de quantas linhas atualizou o histórico e quantas ficaram sem pessoa correspondente.","estado":"rascunho","mvp":false,"path":"modules/pessoas/cadastro-pessoas/f-carregar-historico-participacao.md","codigo":{"back":[],"front":[]}}]}]}],"kpi":{"dominios":3,"fss":6,"feats":55,"fssVazios":0,"domsVazios":0,"codBackend":null,"codFrontend":null,"featComBack":0,"featComFront":0,"arqBack":0,"arqFront":0,"featComObjeto":55,"featComUso":55},"registros":{"back":[],"front":[]}};
